```javascript
function formatItemLabels($items) {
    var $arr = Array();

    $items.forEach(function($item, index) {
        if($item.highlighted.includes("_")) {
            $keyValue = $item.highlighted.split('_');
            $items[index].highlighted = $keyValue[1];
            $arr[$keyValue[0]] = $item;
        }
    });
    return $arr;
}
```

